pub const SCHEMA_VERSION: u32 = 9;

#[derive(Debug, Clone)]
pub struct IndexOptions {
    pub lsp: bool,
    pub watch_status: String,
    pub watcher_mode: String,
    pub index_generation: u64,
    pub last_error: Option<String>,
}

impl Default for IndexOptions {
    fn default() -> Self {
        Self {
            lsp: false,
            watch_status: "unwatched".to_string(),
            watcher_mode: "none".to_string(),
            index_generation: 0,
            last_error: None,
        }
    }
}

pub fn build_index(root: &Path) -> Result<CodeIndex> {
    build_index_with_options(root, IndexOptions::default())
}

pub fn build_index_with_options(root: &Path, options: IndexOptions) -> Result<CodeIndex> {
    let root = root
        .canonicalize()
        .with_context(|| format!("failed to resolve repo root {}", root.display()))?;
    let mut warnings = Vec::new();
    let mut files = Vec::new();
    let mut symbols = Vec::new();
    let mut imports = Vec::new();
    let mut file_contents = Vec::new();
    let ownership_resolver = self::ownership::OwnershipResolver::from_repo_root(&root)
        .filter(|resolver| !resolver.is_empty());
    let git_signals = self::git::collect_git_signals(&root);

    for relative_path in walker::source_files(&root)? {
        let absolute_path = root.join(&relative_path);
        let path_string = path_to_string(&relative_path);
        let language = Language::from_path(&relative_path).expect("walker only returns languages");
        let bytes = match fs::read(&absolute_path) {
            Ok(bytes) => bytes,
            Err(error) => {
                warnings.push(format!("skipped unreadable file {path_string}: {error}"));
                continue;
            }
        };
        let content = match String::from_utf8(bytes.clone()) {
            Ok(content) => content,
            Err(_) => {
                warnings.push(format!("skipped non-UTF8 file {path_string}"));
                continue;
            }
        };
        let metadata = fs::metadata(&absolute_path)
            .with_context(|| format!("failed to stat {}", absolute_path.display()))?;
        let file_id = file_id(&path_string);
        let ownership = ownership_resolver.as_ref().and_then(|resolver| {
            let computed = resolver.ownership_for(&path_string);
            if computed.is_empty() {
                None
            } else {
                Some(computed)
            }
        });
        let file = FileRecord {
            id: file_id.clone(),
            path: path_string.clone(),
            language,
            size_bytes: metadata.len(),
            line_count: content.lines().count(),
            mtime: metadata_mtime(&metadata),
            content_hash: stable_content_hash(&bytes),
            is_test: is_test_file(&path_string),
            is_config: is_config_file(&path_string),
            module_path: module_path(&relative_path),
            content_terms: content_terms(&content, language),
            ownership,
            git: git_signals.get(&path_string).cloned(),
        };

        if language.is_code() {
            for symbol in symbols::extract_symbols(&content, language) {
                symbols.push(SymbolRecord {
                    id: symbol_id(&path_string, symbol.start_line, &symbol.name),
                    file_id: file_id.clone(),
                    name: symbol.name,
                    kind: symbol.kind,
                    language,
                    start_line: symbol.start_line,
                    end_line: symbol.end_line,
                    visibility: symbol.visibility,
                    parent: symbol.parent,
                    signature: symbol.signature,
                    doc: symbol.doc,
                });
            }

            for import in imports::extract_imports(&content, language) {
                imports.push(ImportRecord {
                    file_id: file_id.clone(),
                    source_path: path_string.clone(),
                    resolved_path: resolve_import(
                        &root,
                        &relative_path,
                        language,
                        &import.imported,
                    ),
                    imported: import.imported,
                    aliases: import
                        .aliases
                        .into_iter()
                        .map(|alias| ImportAliasRecord {
                            local: alias.local,
                            imported: alias.imported,
                        })
                        .collect(),
                });
            }
        }

        files.push(file);
        file_contents.push((file_id, path_string, language, content));
    }

    files.sort_by(|left, right| left.path.cmp(&right.path));
    symbols.sort_by(|left, right| {
        left.file_id
            .cmp(&right.file_id)
            .then(left.start_line.cmp(&right.start_line))
            .then(left.name.cmp(&right.name))
    });
    imports.sort_by(|left, right| {
        left.source_path
            .cmp(&right.source_path)
            .then(left.imported.cmp(&right.imported))
    });
    let mut references = build_references(&file_contents, &files, &symbols, &imports);
    let mut lsp_enriched = false;
    if options.lsp {
        let lsp_references = lsp::enrich_references(&root, &file_contents, &files, &symbols);
        lsp_enriched = !lsp_references.is_empty();
        references = merge_references(references, lsp_references);
    }
    references.sort_by(|left, right| {
        left.source_path
            .cmp(&right.source_path)
            .then(left.line.cmp(&right.line))
            .then(left.target_name.cmp(&right.target_name))
            .then(left.kind.cmp(&right.kind))
    });

    let lsp_servers = lsp::server_statuses(&files);
    let indexed_at = now_unix_seconds();

    Ok(CodeIndex {
        schema_version: SCHEMA_VERSION,
        root: ".".to_string(),
        files,
        symbols,
        imports,
        references,
        metadata: IndexMetadata {
            indexed_at,
            watch_status: options.watch_status,
            watcher_mode: options.watcher_mode,
            index_generation: options.index_generation,
            lsp_enriched,
            lsp_enriched_at: if lsp_enriched { indexed_at } else { 0 },
            last_error: options.last_error,
            lsp_servers,
        },
        warnings,
    })
}

pub fn path_to_string(path: &Path) -> String {
    path.to_string_lossy().replace('\\', "/")
}

fn file_id(path: &str) -> String {
    format!("file:{path}")
}

fn symbol_id(path: &str, line: usize, name: &str) -> String {
    format!("symbol:{path}:{line}:{name}")
}

pub(crate) fn metadata_mtime(metadata: &fs::Metadata) -> u64 {
    metadata
        .modified()
        .ok()
        .and_then(|time| time.duration_since(UNIX_EPOCH).ok())
        .map(|duration| duration.as_secs())
        .unwrap_or_default()
}

fn now_unix_seconds() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or_default()
}

/// Fingerprint of the indexed file set and contents: stable across machines
/// and build times because it hashes only file ids and content hashes.
pub fn index_fingerprint(index: &crate::store::CodeIndex) -> String {
    let mut bytes = Vec::new();
    for file in &index.files {
        bytes.extend_from_slice(file.id.as_bytes());
        bytes.push(0);
        bytes.extend_from_slice(file.content_hash.as_bytes());
        bytes.push(b'\n');
    }
    stable_content_hash(&bytes)
}

pub(crate) fn stable_content_hash(bytes: &[u8]) -> String {
    let mut hash = 0xcbf29ce484222325_u64;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("fnv1a64:{hash:016x}")
}

fn module_path(path: &Path) -> String {
    path.parent().map(path_to_string).unwrap_or_default()
}

use super::{language::Language, tree_sitter_symbols};

#[derive(Debug, Clone)]
pub struct RawSymbol {
    pub name: String,
    pub kind: String,
    pub start_line: usize,
    pub end_line: usize,
    pub visibility: String,
    pub parent: Option<String>,
    pub signature: String,
    pub doc: Option<String>,
}

pub fn extract_symbols(content: &str, language: Language) -> Vec<RawSymbol> {
    if !language.is_code() {
        return Vec::new();
    }

    if let Some(symbols) = tree_sitter_symbols::extract_symbols(content, language)
        && !symbols.is_empty()
    {
        return symbols;
    }

    extract_symbols_fallback(content, language)
}

fn extract_symbols_fallback(content: &str, language: Language) -> Vec<RawSymbol> {
    let lines: Vec<&str> = content.lines().collect();
    let mut symbols = Vec::new();

    for (index, line) in lines.iter().enumerate() {
        if let Some((name, kind, visibility)) = parse_line(line, language) {
            let start_line = index + 1;
            symbols.push(RawSymbol {
                name,
                kind,
                start_line,
                end_line: estimate_end_line(&lines, index, language),
                visibility,
                parent: None,
                signature: compact_signature(line),
                doc: previous_doc_comment(&lines, index, language),
            });
        }
    }

    assign_parents(&mut symbols);
    symbols
}

fn parse_line(line: &str, language: Language) -> Option<(String, String, String)> {
    match language {
        Language::Rust => parse_rust_line(line),
        Language::TypeScript | Language::JavaScript => parse_js_line(line),
        Language::Python => parse_python_line(line),
        Language::Php => parse_php_line(line),
        Language::Go => parse_go_line(line),
        Language::Java => parse_java_line(line),
        Language::CSharp => parse_csharp_line(line),
        Language::C => parse_c_line(line),
        Language::Cpp => parse_cpp_line(line),
        Language::Ruby => parse_ruby_line(line),
        Language::Kotlin => parse_kotlin_line(line),
        Language::Swift => parse_swift_line(line),
        Language::Scala => parse_scala_line(line),
        Language::Dart => parse_dart_line(line),
        Language::Lua => parse_lua_line(line),
        Language::Shell => parse_shell_line(line),
        Language::Markdown | Language::Json | Language::Toml | Language::Yaml | Language::Text => {
            None
        }
    }
}

fn parse_rust_line(line: &str) -> Option<(String, String, String)> {
    let trimmed = line.trim_start();
    let exported = trimmed.starts_with("pub ");
    let mut rest = strip_rust_visibility(trimmed);
    rest = rest.strip_prefix("async ").unwrap_or(rest).trim_start();

    for (prefix, kind) in [
        ("fn ", "function"),
        ("struct ", "struct"),
        ("enum ", "enum"),
        ("trait ", "trait"),
        ("impl ", "impl"),
        ("mod ", "module"),
    ] {
        if let Some(after_prefix) = rest.strip_prefix(prefix) {
            return Some((
                take_identifier(after_prefix)?,
                kind.to_string(),
                if exported { "public" } else { "private" }.to_string(),
            ));
        }
    }

    None
}

fn strip_rust_visibility(line: &str) -> &str {
    if let Some(rest) = line.strip_prefix("pub ") {
        return rest.trim_start();
    }

    if line.starts_with("pub(")
        && let Some(end) = line.find(')')
    {
        return line[end + 1..].trim_start();
    }

    line
}

fn parse_js_line(line: &str) -> Option<(String, String, String)> {
    let mut rest = line.trim_start();
    let mut visibility = "local";

    if let Some(after_export) = rest.strip_prefix("export default ") {
        rest = after_export.trim_start();
        visibility = "exported";
    } else if let Some(after_export) = rest.strip_prefix("export ") {
        rest = after_export.trim_start();
        visibility = "exported";
    }

    rest = rest.strip_prefix("async ").unwrap_or(rest).trim_start();

    for (prefix, kind) in [
        ("function ", "function"),
        ("class ", "class"),
        ("interface ", "interface"),
        ("type ", "type"),
    ] {
        if let Some(after_prefix) = rest.strip_prefix(prefix) {
            return Some((
                take_identifier(after_prefix)?,
                kind.to_string(),
                visibility.to_string(),
            ));
        }
    }

    for prefix in ["const ", "let ", "var "] {
        if let Some(after_prefix) = rest.strip_prefix(prefix) {
            let name = take_identifier(after_prefix)?;
            let kind = if is_react_component_candidate(&name, after_prefix) {
                "component"
            } else if after_prefix.contains("=>") || after_prefix.contains("function") {
                "function"
            } else {
                "constant"
            };
            return Some((name, kind.to_string(), visibility.to_string()));
        }
    }

    if let Some(name) = parse_js_method(rest) {
        return Some((name, "method".to_string(), visibility.to_string()));
    }

    None
}

fn is_react_component_candidate(name: &str, rest: &str) -> bool {
    name.chars()
        .next()
        .is_some_and(|character| character.is_ascii_uppercase())
        && (rest.contains("=> <") || rest.contains("React.createElement"))
}

fn parse_python_line(line: &str) -> Option<(String, String, String)> {
    let rest = line.trim_start();

    for (prefix, kind) in [
        ("async def ", "function"),
        ("def ", "function"),
        ("class ", "class"),
    ] {
        if let Some(after_prefix) = rest.strip_prefix(prefix) {
            let name = take_identifier(after_prefix)?;
            let visibility = if name.starts_with('_') {
                "private"
            } else {
                "public"
            };
            return Some((name, kind.to_string(), visibility.to_string()));
        }
    }

    None
}

fn parse_php_line(line: &str) -> Option<(String, String, String)> {
    let trimmed = line.trim_start().trim_start_matches("<?php").trim_start();
    let visibility = visibility_from_modifiers(trimmed, "public");
    let rest = strip_leading_modifiers(
        trimmed,
        &[
            "abstract",
            "final",
            "readonly",
            "public",
            "private",
            "protected",
            "static",
        ],
    );

    for (prefix, kind) in [
        ("function ", "function"),
        ("class ", "class"),
        ("interface ", "interface"),
        ("trait ", "trait"),
        ("enum ", "enum"),
    ] {
        if let Some(after_prefix) = rest.strip_prefix(prefix) {
            return Some((
                take_identifier(after_prefix)?,
                kind.to_string(),
                visibility.to_string(),
            ));
        }
    }

    None
}

fn parse_go_line(line: &str) -> Option<(String, String, String)> {
    let rest = line.trim_start();

    if let Some(after_prefix) = rest.strip_prefix("func ") {
        let function_name = if let Some(receiver_stripped) = after_prefix.strip_prefix('(') {
            let receiver_end = receiver_stripped.find(')')?;
            receiver_stripped[receiver_end + 1..].trim_start()
        } else {
            after_prefix
        };
        let name = take_identifier(function_name)?;
        return Some((
            name.clone(),
            "function".to_string(),
            go_visibility(&name).to_string(),
        ));
    }

    if let Some(after_prefix) = rest.strip_prefix("type ") {
        let name = take_identifier(after_prefix)?;
        let kind = if after_prefix.contains(" struct") {
            "struct"
        } else if after_prefix.contains(" interface") {
            "interface"
        } else {
            "type"
        };
        return Some((
            name.clone(),
            kind.to_string(),
            go_visibility(&name).to_string(),
        ));
    }

    None
}

fn parse_java_line(line: &str) -> Option<(String, String, String)> {
    parse_c_style_line(
